extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var info_script = instantiate_script("res://version_info.gd")
	if not check("script_exists", info_script != null, "Lo script res://version_info.gd deve esistere e potersi istanziare"):
		return
	var version = get_prop(info_script, "VERSION", "")
	check("version_const", str(version) == "1.0.0", "La costante VERSION deve essere '1.0.0'")
	var ignored = get_prop(info_script, "IGNORED_PATHS", [])
	check("ignored_paths", typeof(ignored) == TYPE_ARRAY and ignored.has(".godot/") and ignored.has("*.translation"), "La costante IGNORED_PATHS deve contenere '.godot/' e '*.translation'")
	var info_text = call_if_exists(info_script, "get_info", [], "")
	check("get_info_func", str(info_text) == "Quiz v1.0.0", "La funzione get_info() deve restituire 'Quiz v1.0.0'")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var menu := await instantiate_scene("res://menu.tscn")
	if not check("menu", menu != null, "La scena menu.tscn deve caricarsi senza errori"):
		return
	var label := find_by_name(menu, "VersionLabel") as Label
	if not check("version_label", label != null, "La scena menu.tscn deve contenere un Label chiamato VersionLabel"):
		return
	check("label_text", label.text == "v1.0.0", "Il testo di VersionLabel deve essere 'v1.0.0' (trovato: '%s')" % label.text)

