extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var results_text := source_of("res://results.gd")
	check("results_not_empty", not results_text.is_empty(), "Il file res://results.gd deve essere presente")
	check("results_original", results_text.contains("score_label.text = \"Punteggio: \" + str(QuizData.score)"), "Il file res://results.gd non deve contenere modifiche errate ed essere ripristinato allo stato originale")

extends "res://htd/htd_test.gd"


func _run_tests() -> void:
	var stats_script = load("res://quiz_stats.gd")
	if not check("script_loaded", stats_script != null, "Lo script res://quiz_stats.gd deve caricarsi senza errori"):
		return

	var inst = stats_script.new()
	if not check("inst_not_null", inst != null, "La classe QuizStats deve potersi istanziare"):
		return

	if not check("has_func", has_function(inst, "calculate_accuracy"), "La classe QuizStats deve avere la funzione calculate_accuracy"):
		return

	var acc1 = call_if_exists(inst, "calculate_accuracy", [3, 4], -1.0)
	check("acc_normal", typeof(acc1) in [TYPE_FLOAT, TYPE_INT] and absf(float(acc1) - 75.0) < 0.01, "calculate_accuracy(3, 4) deve restituire 75.0 (restituito: %s)" % str(acc1))

	var acc_zero = call_if_exists(inst, "calculate_accuracy", [0, 5], -1.0)
	check("acc_zero", typeof(acc_zero) in [TYPE_FLOAT, TYPE_INT] and absf(float(acc_zero) - 0.0) < 0.01, "calculate_accuracy(0, 5) deve restituire 0.0 (restituito: %s)" % str(acc_zero))

	var acc_invalid = call_if_exists(inst, "calculate_accuracy", [5, 0], -1.0)
	check("acc_invalid", typeof(acc_invalid) in [TYPE_FLOAT, TYPE_INT] and absf(float(acc_invalid) - 0.0) < 0.01, "calculate_accuracy(5, 0) con totale <= 0 deve restituire 0.0 (restituito: %s)" % str(acc_invalid))
